// Ethernet_PCS_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module Ethernet_PCS_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_cfg_bypass_corr,
  input logic  c_cfg_bypass_ind,
  input logic [2:0] c_tx_am_sf,
  input logic [263:0] c_tx_in_data,
  input logic [639:0] c_tx_out_data,
  input logic  c_tx_out_first,
  input logic [639:0] c_rx_in_data,
  input logic  c_rx_in_first,
  input logic [263:0] c_rx_out_data,
  input logic  c_rx_am_lock,
  input logic [2:0] c_rx_am_sf,
  input logic [3:0] c_st_nsym_a,
  input logic [3:0] c_st_nsym_b,
  input logic  c_tx_in_valid,
  input logic  c_tx_in_ready,
  input logic  c_tx_out_valid,
  input logic  c_tx_out_ready,
  input logic  c_rx_in_valid,
  input logic  c_rx_in_ready,
  input logic  c_rx_out_valid,
  input logic  c_rx_out_ready,
  input logic  c_ev_am_err,
  input logic  c_ev_itb,
  input logic  c_ev_corr_a,
  input logic  c_ev_corr_b,
  input logic  c_ev_uncorr_a,
  input logic  c_ev_uncorr_b,
  input logic  c_ev_resync
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 67;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:66];          // model of every stored word
  logic [12:0] m_set;                // interrupt bits set this clock
  logic m_state_TX_IN;          // full / valid pulse / available
  logic m_state_TX_OUT;          // full / valid pulse / available
  logic m_state_RX_IN;          // full / valid pulse / available
  logic m_state_RX_OUT;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_ev_am_err) m_set[0] = 1'b1;
    if (c_ev_itb) m_set[1] = 1'b1;
    if (c_ev_corr_a) m_set[2] = 1'b1;
    if (c_ev_corr_b) m_set[3] = 1'b1;
    if (c_ev_uncorr_a) m_set[4] = 1'b1;
    if (c_ev_uncorr_b) m_set[5] = 1'b1;
    if (c_ev_resync) m_set[6] = 1'b1;
    if (m_state_TX_IN && c_tx_in_ready) m_set[7] = 1'b1;
    if (m_wr && m_map && (m_idx == 6 || m_idx == 7 || m_idx == 8 || m_idx == 9 || m_idx == 10 || m_idx == 11 || m_idx == 12 || m_idx == 13 || m_idx == 14) && m_state_TX_IN) m_set[8] = 1'b1;
    if (c_tx_out_valid && !m_state_TX_OUT) m_set[9] = 1'b1;
    if (c_tx_out_valid && m_state_TX_OUT && (m_rd && m_map && m_idx == 35)) m_set[9] = 1'b1;
    if (m_state_RX_IN && c_rx_in_ready) m_set[10] = 1'b1;
    if (m_wr && m_map && (m_idx == 36 || m_idx == 37 || m_idx == 38 || m_idx == 39 || m_idx == 40 || m_idx == 41 || m_idx == 42 || m_idx == 43 || m_idx == 44 || m_idx == 45 || m_idx == 46 || m_idx == 47 || m_idx == 48 || m_idx == 49 || m_idx == 50 || m_idx == 51 || m_idx == 52 || m_idx == 53 || m_idx == 54 || m_idx == 55 || m_idx == 56) && m_state_RX_IN) m_set[11] = 1'b1;
    if (c_rx_out_valid && !m_state_RX_OUT) m_set[12] = 1'b1;
    if (c_rx_out_valid && m_state_RX_OUT && (m_rd && m_map && m_idx == 65)) m_set[12] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_w[22] <= 32'h0;
      m_w[23] <= 32'h0;
      m_w[24] <= 32'h0;
      m_w[25] <= 32'h0;
      m_w[26] <= 32'h0;
      m_w[27] <= 32'h0;
      m_w[28] <= 32'h0;
      m_w[29] <= 32'h0;
      m_w[30] <= 32'h0;
      m_w[31] <= 32'h0;
      m_w[32] <= 32'h0;
      m_w[33] <= 32'h0;
      m_w[34] <= 32'h0;
