      if (m_wr && m_map && m_idx == 14 && !m_state_TX_IN) m_w[14] <= ((m_w[14] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 14 && !m_state_TX_IN) m_state_TX_IN <= 1;
      if (m_state_TX_IN && c_tx_in_ready) m_state_TX_IN <= 0;
