      if (m_wr && m_map && m_idx == 42 && !m_state_RX_IN) m_w[42] <= ((m_w[42] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 43 && !m_state_RX_IN) m_w[43] <= ((m_w[43] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 44 && !m_state_RX_IN) m_w[44] <= ((m_w[44] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 45 && !m_state_RX_IN) m_w[45] <= ((m_w[45] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 46 && !m_state_RX_IN) m_w[46] <= ((m_w[46] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 47 && !m_state_RX_IN) m_w[47] <= ((m_w[47] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 48 && !m_state_RX_IN) m_w[48] <= ((m_w[48] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 49 && !m_state_RX_IN) m_w[49] <= ((m_w[49] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 50 && !m_state_RX_IN) m_w[50] <= ((m_w[50] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 51 && !m_state_RX_IN) m_w[51] <= ((m_w[51] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 52 && !m_state_RX_IN) m_w[52] <= ((m_w[52] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
