      if (m_wr && m_map && m_idx == 55 && !m_state_RX_IN) m_w[55] <= ((m_w[55] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 56 && !m_state_RX_IN) m_w[56] <= ((m_w[56] & ~m_be) | (PWDATA & m_be)) & 32'h1;
      if (m_wr && m_map && m_idx == 56 && !m_state_RX_IN) m_state_RX_IN <= 1;
      if (m_state_RX_IN && c_rx_in_ready) m_state_RX_IN <= 0;
      if (c_rx_out_valid && (!m_state_RX_OUT || (m_rd && m_map && m_idx == 65))) begin
        m_w[57] <= (32'(c_rx_out_data[31:0]) << 0);
        m_w[58] <= (32'(c_rx_out_data[63:32]) << 0);
        m_w[59] <= (32'(c_rx_out_data[95:64]) << 0);
        m_w[60] <= (32'(c_rx_out_data[127:96]) << 0);
        m_w[61] <= (32'(c_rx_out_data[159:128]) << 0);
        m_w[62] <= (32'(c_rx_out_data[191:160]) << 0);
        m_w[63] <= (32'(c_rx_out_data[223:192]) << 0);
        m_w[64] <= (32'(c_rx_out_data[255:224]) << 0);
        m_w[65] <= (32'(c_rx_out_data[263:256]) << 0);
        m_state_RX_OUT <= 1;
      end else if ((m_rd && m_map && m_idx == 65)) m_state_RX_OUT <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h45500100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_RX_OUT, m_state_RX_IN, m_state_TX_OUT, m_state_TX_IN});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
